from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

BASE="output/assessment-2026-10-31/"
s=getSampleStyleSheet()
s.add(ParagraphStyle(name="T",parent=s['Title'],fontName='Helvetica-Bold',fontSize=22,leading=26,alignment=TA_CENTER,textColor=colors.HexColor('#102A43'),spaceAfter=8))
s.add(ParagraphStyle(name="S",parent=s['Normal'],fontSize=9,leading=12,alignment=TA_CENTER,textColor=colors.HexColor('#486581'),spaceAfter=14))
s.add(ParagraphStyle(name="H",parent=s['Heading1'],fontName='Helvetica-Bold',fontSize=15,leading=18,textColor=colors.HexColor('#102A43'),spaceBefore=8,spaceAfter=6))
s.add(ParagraphStyle(name="B",parent=s['BodyText'],fontSize=9,leading=12.4,textColor=colors.HexColor('#243B53'),spaceAfter=5))
s.add(ParagraphStyle(name="SM",parent=s['BodyText'],fontSize=7.6,leading=9.8,textColor=colors.HexColor('#243B53')))
s.add(ParagraphStyle(name="C",parent=s['BodyText'],fontSize=9.5,leading=13,textColor=colors.HexColor('#102A43'),backColor=colors.HexColor('#EAF4FF'),borderColor=colors.HexColor('#9FB3C8'),borderWidth=.5,borderPadding=7,spaceAfter=8))
def p(x,k='B'): return Paragraph(x,s[k])
def t(rows,widths):
 x=Table([[p(v,'SM') for v in r] for r in rows],colWidths=widths,repeatRows=1)
 x.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#243B53')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#BCCCDC')),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F0F4F8')]),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return x
def footer(name):
 def f(c,d):
  c.saveState();c.setStrokeColor(colors.HexColor('#D9E2EC'));c.line(18*mm,14*mm,192*mm,14*mm);c.setFont('Helvetica',7);c.setFillColor(colors.HexColor('#627D98'));c.drawString(18*mm,9*mm,'License Manager - 31 Oct 2026');c.drawRightString(192*mm,9*mm,f'{name} | Page {d.page}');c.restoreState()
 return f
def build(path,title,sub,story,name):
 d=SimpleDocTemplate(path,pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=15*mm,bottomMargin=20*mm);z=[Spacer(1,13*mm),p('License Manager','T'),p(title,'T'),p(sub,'S')]+story;d.build(z,onFirstPage=footer(name),onLaterPages=footer(name))
common=[p('Verified position','H'),p('The authenticated local application was inspected read-only. Reconciliation displayed 1,043 BOEs, 317 import invoices, 2 matched, 53 unmatched invoices and 1,699 duplicate-debit findings. These are confirmed as screen metrics, not confirmed financial errors: their query/counting semantics require source-record validation. Dashboard displayed 109 Missing DGFT records; E1 planning displayed 2 validation issues. No data mutation or accounting operation was performed.','C')]
a=common+[p('What this option delivers','H'),p('A reliable, small-business operational control system for licences, DFIA/SION planning, allotments, BOEs, trades, invoices, transfers, documents, reports and BOE-invoice reconciliation. It gives one or two employees simple intake and the owner a focused exception dashboard.','B'),t([['Work package','Outcome','Likely person-days'],['Evidence/test harness','Metric semantics, golden data, isolated DB/Redis','18'],['Company isolation','Scoped UI/API/export/job access','45'],['Canonical calculations','One balance/restriction contract and parity','65'],['Restriction planning','Versioned groups/pools/AU/explanation/concurrency','70'],['BOE/invoice/reconciliation','Safe correction, data triage, source evidence','95'],['Dashboard/UX/reports','Actionable queues, reliable exports','85'],['Hardening/UAT','Recovery/security/performance/training','67']], [43*mm,80*mm,39*mm]),p('Mandatory safeguards','H'),p('No cross-company access; no concurrent capacity overspend; impact preview/reason/audit for BOE merge/delete, allocation reversal and restriction changes; immutable evidence before data correction; source-to-export parity. Operational reconciliation remains included, but general ledger, bank accounting, GST/TDS accounting and accounting close remain excluded.','C'),p('Roadmap and acceptance','H'),p('Phase 0 baseline; Phase 1 containment; Phase 2 calculations; Phase 3 restrictions; Phase 4 BOE/invoice remediation; Phase 5 dashboard/UX; Phase 6 release readiness. Release requires isolated end-to-end evidence, calculation/export parity, tenant negative tests, backup/restore drill, and owner UAT.','B'),p('Effort and decision','H'),p('Estimate: 237/445/770 developer-days low/likely/high. For a single developer at roughly 3.5 productive days per week, expect 13-18 months; a small team can reduce elapsed time only after baseline/contracts. Select this option when external accounting remains adequate and fastest operational reliability is the owner priority.','C')]
b=common+[p('What this option adds','H'),p('All Option A deliverables plus company-wise accounting: tenant/legal entity boundary, chart of accounts, periods/opening balances, immutable balanced vouchers/journals, source-document posting, AR/AP, payments/receipts, cash/bank, statements and controlled bank reconciliation.','B'),t([['Accounting layer','Required result','Likely person-days'],['Policy/design','CA-approved entity/chart/period/source policy','25'],['Journal foundation','Draft/approved/posted/reversed vouchers; debit=credit','120'],['Subledgers/bridge','AR/AP, payments, advances, post-once bridge','75'],['Bank reconciliation','CSV/XLSX, dedupe, match/review/close/reopen','80'],['Migration/cutover','Opening mapping, parallel reconcile, exception queue','130']], [43*mm,80*mm,39*mm]),p('Financial controls','H'),p('Every posted voucher must balance and be immutable; corrections create reversals. Operational source records post once through idempotency references. AR/AP must reconcile to control accounts. Banking uses explainable suggestions and manual review; no automatic book entry without approved policy. Tax, GST, TDS and Tally require CA review and are not inferred from fields.','C'),p('Roadmap and acceptance','H'),p('Finish Option A integrity/isolation first, then accounting policy/design, journal foundation, subledgers/source bridge, controlled opening-balance cutover, bank reconciliation and optional advanced tax/Tally work. Acceptance: journal invariant, immutable/reversal history, subledger/GL/trial-balance reconciliation, scoped accounting data, duplicate-safe statement imports and CA/owner cutover sign-off.','B'),p('Effort and decision','H'),p('Option B adds 175/330/600 days for core accounting; including advanced tax/Tally raises the addition to 235/460/860. Full scope is 412/775/1,370 days before advanced accounting. Choose it only when in-app AR/AP, cash/bank visibility and a CA-supported cutover are materially needed; it is not required to improve licence operations.','C')]
c=common+[p('Decision summary','H'),t([['Dimension','Option A','Option B'],['Primary value','Reliable licence operations sooner','Operations plus internal financial control'],['Accounting','Excluded','New GL/AR/AP/bank foundation'],['Likely effort','445 days','775 days core'],['Solo maintenance','Lower','Higher policy/control burden'],['Migration risk','Operational data remediation','Operational plus accounting cutover'],['Recommended when','1-2 staff use external accountant/Tally','External accounting blocks daily control and CA is available']], [36*mm,63*mm,63*mm]),p('Recommendation','H'),p('Choose Option A first. It addresses the verified risks that most directly threaten a small business: data integrity, operational reconciliation, licence/restriction correctness and company isolation. Make Option A accounting-ready through stable company/source-document references, but do not prematurely build journals.','C'),p('When Option B is preferable','H'),p('Choose Option B now only if the owner needs reliable in-app receivables/payables, expenses, cash/bank visibility and financial close, accepts the longer implementation/cutover, and can obtain CA-approved chart, tax, opening-balance and migration decisions.','B'),p('Owner decisions before approval','H'),p('Confirm internal vs external SaaS target; restriction/AU definitions and authoritative evidence; historic correction policy; approval thresholds; essential reports; accounting now/later; and, if B, chart/period/tax/Tally/bank format/cutover owner.','C')]
build(BASE+'LICENSE_MANAGER_SCOPE_WITHOUT_ACCOUNTING.pdf','Scope without accounting','Management report | Option A | 31 October 2026',a,'Option A')
build(BASE+'LICENSE_MANAGER_SCOPE_WITH_ACCOUNTING.pdf','Scope with integrated accounting','Management report | Option B | 31 October 2026',b,'Option B')
build(BASE+'LICENSE_MANAGER_MANAGEMENT_DECISION_REPORT.pdf','Management decision report','Option A versus Option B | 31 October 2026',c,'Decision')
print('done')
